
export const EXERCISE_CATALOG = [
  { id: 'ex-1', name: 'Dumbbell Shrugs', name_i18n: { es: 'Encogimientos con mancuernas' }, category: 'Free weight', muscles: {     traps: 1 }, description: 'Stand upright with a dumbbell in each hand, arms fully extended at your sides, and palms facing your body. Keep your chest lifted, shoulders pulled slightly back, and core engaged. Without bending your elbows, lift your shoulders straight up toward your ears as high as you can. Focus on contracting your trapezius muscles at the top of the movement. Pause briefly, then slowly lower your shoulders back down under control. Avoid rolling or rotating the shoulders - the motion should be vertical and controlled.', description_i18n: { es: 'De pie con una mancuerna en cada mano, brazos extendidos a los lados y palmas hacia el cuerpo. Mantiene el pecho alto, hombros ligeramente atras y el core activo. Sin doblar los codos, eleva los hombros hacia las orejas lo mas alto posible. Contrae los trapecios en la parte alta. Pausa breve y baja de forma controlada. Evita rodar o rotar los hombros; el movimiento debe ser vertical y controlado.' }, image: require('../assets/workout-api-images/dumbbell-shrugs.svg') },
  { id: 'ex-2', name: 'Front Raise with Dumbbells', name_i18n: { es: 'Elevacion frontal con mancuernas' }, category: 'Free weight', muscles: {     shoulders: 1 }, description: 'Stand upright with a dumbbell in each hand, arms extended down in front of your thighs, and palms facing your body. Keep your chest lifted, shoulders relaxed, and engage your core. Raise one or both arms straight in front of you until they reach shoulder height, keeping your elbows slightly bent and wrists neutral. Pause briefly at the top to contract your shoulder muscles. Lower the dumbbells slowly and under control back to the starting position. Avoid using momentum or swinging your body during the movement.', description_i18n: { es: 'De pie con una mancuerna en cada mano, brazos extendidos frente a los muslos y palmas hacia el cuerpo. Mantiene el pecho alto, hombros relajados y el core activo. Eleva uno o ambos brazos al frente hasta la altura de los hombros, con codos ligeramente flexionados y muñecas neutras. Pausa breve arriba y baja de forma controlada. Evita usar impulso o balancear el cuerpo.' }, image: require('../assets/workout-api-images/front-raise-with-dumbbells.svg') },
  { id: 'ex-3', name: 'Dumbbell Shoulder Press', name_i18n: { es: 'Press de hombros con mancuernas' }, category: 'Free weight', muscles: {     shoulders: 0.8,     traps: 0.1,     triceps: 0.1 }, description: 'Sit on a bench with back support and hold a dumbbell in each hand resting on your thighs. Using your legs, help lift the dumbbells up to shoulder height, elbows bent and palms facing forward. Press the dumbbells upward until your arms are fully extended above your head, bringing the weights slightly together at the top without locking your elbows. Lower the dumbbells in a controlled manner back to shoulder level. Keep your core tight and avoid arching your back. This exercise can also be performed standing, but requires strict posture and core engagement.', description_i18n: { es: 'Sientate en un banco con respaldo y sujeta una mancuerna en cada mano sobre los muslos. Usa las piernas para ayudar a subir las mancuernas a la altura de los hombros, con codos flexionados y palmas al frente. Presiona hacia arriba hasta extender los brazos sin bloquear los codos. Baja de forma controlada hasta la altura de los hombros. Mantiene el core firme y evita arquear la espalda. También se puede hacer de pie, pero requiere postura estricta y core activo.' }, image: require('../assets/workout-api-images/dumbbell-shoulder-press.svg') },
  { id: 'ex-4', name: 'Barbell Shoulder Press', name_i18n: { es: 'Press de hombros con barra' }, category: 'Free weight', muscles: {     shoulders: 0.8,     traps: 0.1,     triceps: 0.1 }, description: 'Stand tall with your feet shoulder-width apart and a barbell resting at shoulder level, palms facing forward and elbows slightly in front of the bar. Engage your core and retract your shoulder blades. Press the barbell upward in a straight line until your arms are fully extended above your head without locking the elbows. At the top, keep the bar slightly behind your head for proper alignment. Lower the barbell back to shoulder level with control. Keep your torso upright throughout the movement and avoid leaning back.', description_i18n: { es: 'De pie con los pies al ancho de los hombros y la barra a la altura de los hombros, palmas al frente y codos ligeramente por delante de la barra. Activa el core y retrae las escapulas. Presiona la barra en linea recta hasta extender los brazos sin bloquear los codos. En la parte alta, la barra queda ligeramente detras de la cabeza para una buena alineacion. Baja la barra con control. Mantiene el torso erguido y evita inclinarte hacia atras.' }, image: require('../assets/workout-api-images/barbell-shoulder-press.svg') },
  { id: 'ex-5', name: 'Lateral Raise with Dumbbells', name_i18n: { es: 'Elevacion lateral con mancuernas' }, category: 'Free weight', muscles: {     shoulders: 1 }, description: 'Stand upright with a dumbbell in each hand, arms relaxed at your sides, and palms facing your body. Engage your core and keep your chest lifted. With a slight bend in your elbows, raise both arms out to the sides until they reach shoulder height, keeping the motion smooth and controlled. Pause briefly at the top while contracting your shoulder muscles. Lower the dumbbells slowly back to the starting position. Avoid swinging or using momentum. This exercise can also be performed seated for greater isolation.', description_i18n: { es: 'De pie con una mancuerna en cada mano, brazos relajados a los lados y palmas hacia el cuerpo. Activa el core y mantiene el pecho alto. Con una ligera flexion en los codos, eleva ambos brazos a los lados hasta la altura de los hombros, con movimiento suave y controlado. Pausa breve arriba y baja de forma controlada. Evita balanceo o impulso. Este ejercicio tambien se puede hacer sentado para mayor aislamiento.' }, image: require('../assets/workout-api-images/lateral-raise-with-dumbbells.svg') },
  { id: 'ex-6', name: 'Cable Lateral Raise', name_i18n: { es: 'Elevacion lateral en cable' }, category: 'Cable', muscles: {     shoulders: 1 }, description: 'Set the cable pulley to the lowest position and attach a single handle. Stand sideways to the machine, holding the handle with the hand farthest from the pulley. Let your arm rest alongside your body with a slight bend in the elbow. Engage your core and raise your arm out to the side until it reaches shoulder height, keeping the movement slow and controlled. Pause briefly at the top, then lower the handle back to the starting position. Keep your torso still and avoid swinging. Repeat the movement on the opposite side.', description_i18n: { es: 'Ajusta la polea al punto mas bajo y coloca una manija simple. Ponte de lado a la maquina y sujeta la manija con la mano mas alejada de la polea. Deja el brazo junto al cuerpo con ligera flexion de codo. Activa el core y eleva el brazo al lado hasta la altura de los hombros con un movimiento lento y controlado. Pausa breve arriba y baja con control. Mantiene el torso quieto y evita el balanceo. Repite con el otro lado.' }, image: require('../assets/workout-api-images/cable-lateral-raise.svg') },
  { id: 'ex-7', name: 'Arnold Dumbbell Press', name_i18n: { es: 'Press Arnold con mancuernas' }, category: 'Free weight', muscles: {     shoulders: 0.8,     traps: 0.1,     triceps: 0.1 }, description: 'Sit on a bench with back support, holding a dumbbell in each hand resting on your thighs. Lift the dumbbells to chest level with your palms facing your body and elbows bent in front of you. Begin the press by rotating your wrists outward as you press the weights overhead. At the top of the movement, your arms should be fully extended and your palms facing forward. Reverse the motion as you lower the dumbbells, rotating your wrists back inward to return to the starting position. Keep your core tight and perform the movement in a smooth and controlled manner.', description_i18n: { es: 'Sientate en un banco con respaldo, con una mancuerna en cada mano sobre los muslos. Sube las mancuernas a la altura del pecho con palmas hacia el cuerpo y codos al frente. Inicia el press rotando las muñecas hacia afuera mientras empujas arriba. En la parte alta los brazos quedan extendidos y las palmas al frente. Invierte el movimiento al bajar, rotando las muñecas hacia adentro. Mantiene el core firme y un movimiento suave y controlado.' }, image: require('../assets/workout-api-images/arnold-dumbbell-press.svg') },
  { id: 'ex-8', name: 'Upright Row', name_i18n: { es: 'Remo al menton' }, category: 'Free weight', muscles: {     shoulders: 0.8,     traps: 0.1,     triceps: 0.1 }, description: 'Stand upright holding a barbell with a narrow, overhand grip at hip level. Keep your back straight, chest up, and core engaged. Pull the barbell straight up along your body, leading with your elbows and keeping the bar close to your torso. Raise the bar until it reaches upper chest or neck level, with elbows flaring outward and positioned above the wrists. Pause briefly at the top, then lower the bar slowly and under control back to the starting position. Avoid swinging or using momentum throughout the movement.', description_i18n: { es: 'De pie sujetando una barra con agarre estrecho pronado a la altura de la cadera. Mantiene la espalda recta, el pecho arriba y el core activo. Tira la barra hacia arriba cerca del torso, guiando con los codos. Sube la barra hasta la parte alta del pecho o el cuello, con los codos por encima de las muñecas. Pausa breve arriba y baja con control. Evita el balanceo o el impulso.' }, image: require('../assets/workout-api-images/upright-row.svg') },
  { id: 'ex-9', name: 'Cable Front Raise', name_i18n: { es: 'Elevacion frontal en cable' }, category: 'Cable', muscles: {     shoulders: 1 }, description: 'Set the cable pulley to the lowest position and attach a single handle. Stand facing away from the machine with the handle held in one hand, arm resting alongside your body and palm facing your thigh. Engage your core and raise your arm straight in front of you to shoulder height, keeping your elbow slightly bent and wrist neutral. Pause briefly at the top, then slowly lower the handle back to the starting position with control. Avoid using momentum or leaning backward. Repeat the same motion with the other arm.', description_i18n: { es: 'Ajusta la polea al punto mas bajo y coloca una manija simple. Ponte de espaldas a la maquina con la manija en una mano, brazo junto al cuerpo y palma hacia el muslo. Activa el core y eleva el brazo al frente hasta la altura del hombro, con codo ligeramente flexionado y muñeca neutra. Pausa breve arriba y baja con control. Evita impulso o inclinarte hacia atras. Repite con el otro brazo.' }, image: require('../assets/workout-api-images/cable-front-raise.svg') },
  { id: 'ex-10', name: 'Reverse Fly on Incline Bench', name_i18n: { es: 'Aperturas inversas en banco inclinado' }, category: 'Free weight', muscles: {     shoulders: 0.8,     traps: 0.2 }, description: 'Lie face down on an incline bench with a dumbbell in each hand, arms extended toward the floor and palms facing each other. Keep your chest in contact with the bench and engage your core. With a slight bend in the elbows, raise your arms out to the sides in a wide arc until they reach shoulder height. Focus on squeezing the shoulder blades together at the top. Lower the dumbbells slowly and under control back to the starting position. Avoid using momentum or swinging the arms.', description_i18n: { es: 'Recostado boca abajo en un banco inclinado con una mancuerna en cada mano, brazos extendidos hacia el suelo y palmas enfrentadas. Mantiene el pecho en contacto con el banco y el core activo. Con ligera flexion de codos, eleva los brazos a los lados hasta la altura de los hombros. Aprieta las escapulas arriba. Baja las mancuernas con control. Evita usar impulso o balancear los brazos.' }, image: require('../assets/workout-api-images/reverse-fly-on-incline-bench.svg') },
  { id: 'ex-11', name: 'Incline Dumbbell Reverse Fly', name_i18n: { es: 'Aperturas inversas con mancuernas en banco inclinado' }, category: 'Free weight', muscles: {     shoulders: 0.8,     traps: 0.2 }, description: 'Stand with a dumbbell in each hand, arms extended down at your sides. Hinge forward at the hips with a flat back and slight bend in your knees, bringing your torso close to parallel with the floor. With a slight bend in the elbows, raise your arms out to the sides in a wide arc until they reach shoulder height, squeezing your shoulder blades together at the top. Lower the dumbbells slowly and under control back to the starting position. The movement can also be performed seated on an incline bench for greater stability.', description_i18n: { es: 'De pie con una mancuerna en cada mano y brazos a los lados. Inclina el torso desde las caderas con espalda recta y rodillas ligeramente flexionadas, dejando el torso casi paralelo al suelo. Con ligera flexion en los codos, eleva los brazos a los lados hasta la altura de los hombros, apretando las escapulas arriba. Baja con control. Tambien se puede hacer sentado en un banco inclinado para mayor estabilidad.' }, image: require('../assets/workout-api-images/incline-dumbbell-reverse-fly.svg') },
  { id: 'ex-12', name: 'Cable Reverse Fly', name_i18n: { es: 'Aperturas inversas en cable' }, category: 'Cable', muscles: {     shoulders: 0.8,     traps: 0.2 }, description: 'Stand facing the cable machine with both pulleys set at the highest position. Grab the left handle with your right hand and the right handle with your left hand, so that your arms are crossed in front of you with elbows slightly bent and hands just below shoulder height. Engage your core and pull both arms out and back in a wide arc until your hands are aligned with your shoulders and your arms are perpendicular to your torso. Focus on contracting the rear delts at the peak of the movement. Slowly return to the starting crossed-arm position with control, avoiding momentum or using your back.', description_i18n: { es: 'De pie frente a la maquina con las poleas en la posicion mas alta. Toma la manija izquierda con la mano derecha y la derecha con la mano izquierda, con los brazos cruzados al frente, codos ligeramente flexionados y manos bajo la altura de los hombros. Activa el core y abre los brazos en un arco amplio hasta alinear las manos con los hombros y dejar los brazos perpendiculares al torso. Contrae los deltoides posteriores arriba. Vuelve a la posicion cruzada con control, sin impulso ni uso de la espalda.' }, image: require('../assets/workout-api-images/cable-reverse-fly.svg') },
  { id: 'ex-13', name: 'Face Pull', name_i18n: { es: 'Jalon a la cara' }, category: 'Cable', muscles: {     shoulders: 1 }, description: 'Set the cable pulley to a high position and attach a rope handle. Stand facing the machine and grab each end of the rope with a neutral grip, thumbs pointing toward you. Step back slightly and extend your arms forward, keeping a slight bend in your elbows. Pull the rope toward your face by driving your elbows back and out while squeezing your shoulder blades together. At the end of the movement, your elbows should be at shoulder height, and your forearms should form a 90-degree angle, with the rope spread apart near your face. Reverse the motion slowly to return to the starting position, keeping tension on the cable at all times.', description_i18n: { es: 'Ajusta la polea alta y coloca una cuerda. De pie frente a la maquina, toma cada extremo con agarre neutral, pulgares hacia ti. Da un paso atras y extiende los brazos con ligera flexion. Tira de la cuerda hacia la cara llevando los codos hacia atras y afuera mientras juntas las escapulas. Al final, los codos deben quedar a la altura de los hombros y los antebrazos a 90 deg, con la cuerda separada cerca de la cara. Regresa lento manteniendo tension en el cable.' }, image: require('../assets/workout-api-images/face-pull.svg') },
  { id: 'ex-14', name: 'Reverse Butterfly', name_i18n: { es: 'Mariposa inversa' }, category: 'Machine', muscles: {     shoulders: 0.8,     traps: 0.2 }, description: 'Sit facing the rear side of the butterfly (pec deck) machine and adjust the seat so that your shoulders are aligned with the handles. Grab the handles with a neutral grip and keep your elbows slightly bent. Pull the handles outward and backward in a wide arc, focusing on squeezing your shoulder blades together at the peak of the movement. Keep your chest in contact with the pad and avoid using momentum. Slowly return the handles to the starting position under control to complete the rep.', description_i18n: { es: 'Sientate mirando la parte trasera de la maquina pec deck y ajusta el asiento para alinear los hombros con las manijas. Sujeta las manijas con agarre neutral y codos ligeramente flexionados. Abre las manijas hacia atras en un arco amplio, apretando las escapulas en la parte alta. Mantiene el pecho en el respaldo y evita el impulso. Regresa a la posicion inicial con control.' }, image: require('../assets/workout-api-images/reverse-butterfly.svg') },
  { id: 'ex-15', name: 'Dumbbell Biceps Curl', name_i18n: { es: 'Curl de biceps con mancuernas' }, category: 'Free weight', muscles: {     biceps: 0.8,     forearms: 0.2 }, description: 'Stand upright with a dumbbell in each hand, arms fully extended at your sides and palms facing forward. Keep your elbows close to your torso and your back straight. Curl the dumbbells upward by flexing your elbows, bringing the weights toward your shoulders while keeping your upper arms stationary. Focus on contracting your biceps at the top of the movement. Lower the dumbbells slowly back to the starting position without locking your elbows completely. This exercise can also be performed seated on a bench.', description_i18n: { es: 'De pie con una mancuerna en cada mano, brazos extendidos a los lados y palmas al frente. Mantiene los codos cerca del torso y la espalda recta. Flexiona los codos para subir las mancuernas hacia los hombros, con los brazos superiores fijos. Contrae los biceps arriba. Baja con control sin bloquear los codos. Este ejercicio tambien se puede hacer sentado.' }, image: require('../assets/workout-api-images/dumbbell-biceps-curl.svg') },
  { id: 'ex-16', name: 'Dumbbell Hammer Grip Curl', name_i18n: { es: 'Curl martillo con mancuernas' }, category: 'Free weight', muscles: {     biceps: 0.8,     forearms: 0.2 }, description: 'Stand upright with a dumbbell in each hand, arms extended at your sides and palms facing your body in a neutral grip. Keep your elbows close to your torso and maintain a straight back. Curl the dumbbells upward by bending your elbows, bringing the weights toward your shoulders while keeping the palms facing inward throughout the movement. Squeeze your biceps at the top, then lower the dumbbells slowly and under control back to the starting position without locking your elbows. This exercise can also be performed seated on a bench.', description_i18n: { es: 'De pie con una mancuerna en cada mano, brazos extendidos a los lados y palmas hacia el cuerpo en agarre neutral. Mantiene los codos cerca del torso y la espalda recta. Flexiona los codos para subir las mancuernas hacia los hombros manteniendo las palmas hacia adentro. Aprieta los biceps arriba y baja con control sin bloquear los codos. Este ejercicio tambien se puede hacer sentado.' }, image: require('../assets/workout-api-images/dumbbell-hammer-grip-curl.svg') },
  { id: 'ex-17', name: 'Barbell Curl', name_i18n: { es: 'Curl con barra' }, category: 'Free weight', muscles: {     biceps: 0.8,     forearms: 0.2 }, description: 'Stand upright holding a barbell with both hands using a shoulder-width underhand grip, palms facing forward. Let your arms hang fully extended in front of your thighs. Keep your elbows close to your torso and curl the barbell upward by flexing your elbows, bringing the bar toward your shoulders. Focus on keeping your upper arms stationary and avoid swinging. Squeeze the biceps at the top, then lower the barbell in a controlled manner back to the starting position without locking your elbows. Maintain a straight back throughout the movement.', description_i18n: { es: 'De pie con una barra y agarre supino al ancho de los hombros, palmas al frente. Deja los brazos extendidos frente a los muslos. Mantiene los codos cerca del torso y flexiona para subir la barra hacia los hombros. Los brazos superiores permanecen fijos y evita el balanceo. Aprieta los biceps arriba y baja con control sin bloquear los codos. Mantiene la espalda recta.' }, image: require('../assets/workout-api-images/barbell-curl.svg') },
  { id: 'ex-18', name: 'Biceps Curl Machine', name_i18n: { es: 'Curl de biceps en maquina' }, category: 'Machine', muscles: {     biceps: 0.8,     forearms: 0.2 }, description: 'Adjust the seat height so your upper arms rest comfortably on the arm pad, with your elbows aligned with the machine\'s pivot point. Grasp the handles or bar with an underhand grip. Keeping your upper arms fixed against the pad, curl the weight toward your shoulders by bending your elbows and contracting your biceps. Pause briefly at the top, then lower the weight slowly back to the starting position without fully locking your elbows. Maintain smooth and controlled movement throughout the exercise.', description_i18n: { es: 'Ajusta la altura del asiento para que los brazos descansen en el pad y los codos queden alineados con el eje de la maquina. Sujeta las manijas con agarre supino. Con los brazos fijos, flexiona los codos y sube el peso hacia los hombros. Pausa breve arriba y baja con control sin bloquear los codos. Mantiene un movimiento suave y controlado.' }, image: require('../assets/workout-api-images/biceps-curl-machine.svg') },
  { id: 'ex-19', name: 'Reverse Barbell Curl', name_i18n: { es: 'Curl inverso con barra' }, category: 'Free weight', muscles: {     biceps: 0.5,     forearms: 0.5 }, description: 'Stand upright holding a barbell with both hands using an overhand (pronated) grip, palms facing down, and hands at shoulder-width. Keep your elbows close to your body and your arms fully extended in front of your thighs. Curl the barbell upward by bending your elbows, bringing the bar toward your shoulders while keeping your upper arms stationary. Focus on contracting your forearms and biceps. Lower the bar slowly and under control back to the starting position, without locking your elbows. Maintain a straight posture throughout the movement.', description_i18n: { es: 'De pie con una barra y agarre pronado, palmas hacia abajo y manos al ancho de los hombros. Mantiene los codos cerca del cuerpo y los brazos extendidos frente a los muslos. Flexiona los codos para subir la barra hacia los hombros con los brazos superiores fijos. Enfoca la contraccion en antebrazos y biceps. Baja con control sin bloquear los codos. Mantiene la postura recta.' }, image: require('../assets/workout-api-images/reverse-barbell-curl.svg') },
  { id: 'ex-20', name: 'Spider Curl', name_i18n: { es: 'Curl spider' }, category: 'Free weight', muscles: {     biceps: 0.8,     forearms: 0.2 }, description: 'Lie face down on an incline bench with your chest supported and your arms hanging straight down, holding a dumbbell in each hand with your palms facing forward. Keep your upper arms vertical and stationary. Curl the weights toward your shoulders by bending your elbows and contracting your biceps. Pause briefly at the top, then lower the dumbbells slowly and under control to the starting position, without locking your elbows. This exercise can also be performed using a barbell.', description_i18n: { es: 'Recostado boca abajo en un banco inclinado con el pecho apoyado, deja los brazos colgando y sujeta una mancuerna en cada mano con palmas al frente. Mantiene los brazos superiores verticales y fijos. Flexiona los codos para llevar las mancuernas hacia los hombros. Pausa breve arriba y baja con control sin bloquear los codos. Este ejercicio tambien se puede hacer con barra.' }, image: require('../assets/workout-api-images/spider-curl.svg') },
  { id: 'ex-21', name: 'Biceps Cable Curl', name_i18n: { es: 'Curl de biceps en cable' }, category: 'Cable', muscles: {     biceps: 0.8,     forearms: 0.2 }, description: 'Stand facing a low cable pulley with a straight bar attachment. Grab the bar with an underhand grip, hands about shoulder-width apart, and arms fully extended in front of your thighs. Keep your elbows close to your torso and curl the bar upward by bending your elbows, bringing the bar toward your shoulders. Contract your biceps at the top of the movement. Slowly lower the bar back down to the starting position, maintaining control and avoiding full elbow lockout.', description_i18n: { es: 'De pie frente a una polea baja con barra recta. Toma la barra con agarre supino y manos al ancho de los hombros, con los brazos extendidos frente a los muslos. Mantiene los codos cerca del torso y flexiona para llevar la barra hacia los hombros. Contrae los biceps arriba. Baja con control hasta la posicion inicial evitando bloquear por completo los codos.' }, image: require('../assets/workout-api-images/biceps-cable-curl.svg') },
  { id: 'ex-22', name: 'High Cable Curls', name_i18n: { es: 'Curl en cable alto' }, category: 'Cable', muscles: {     biceps: 1 }, description: 'Stand in the center of a cable crossover machine with both pulleys set at the highest position. Grab a handle in each hand using a supinated grip, and extend your arms out to the sides at shoulder height without locking your elbows. Keep your upper arms parallel to the floor and stationary. Curl the handles toward your head by bending your elbows and contracting your biceps. Pause briefly at the peak of the movement, then slowly return to the starting position while maintaining tension in the cables.', description_i18n: { es: 'De pie en el centro de un crossover con las poleas en la posicion mas alta. Sujeta una manija en cada mano con agarre supino y extiende los brazos a los lados a la altura de los hombros sin bloquear los codos. Mantiene los brazos superiores paralelos al suelo y fijos. Flexiona los codos para llevar las manijas hacia la cabeza. Pausa breve arriba y regresa lento manteniendo la tension en los cables.' }, image: require('../assets/workout-api-images/high-cable-curls.svg') },
  { id: 'ex-23', name: 'Supinated Grip Pull-Ups', name_i18n: { es: 'Dominadas supinas' }, category: 'Body weight', muscles: {     biceps: 0.7,     lats: 0.2,     forearms: 0.1 }, description: 'Grab a pull-up bar with an underhand (supinated) grip, palms facing you, and hands about shoulder-width apart. Start from a dead hang with arms fully extended. Engage your core and pull your chest toward the bar by bending your elbows and squeezing your shoulder blades together. Continue pulling until your chin rises above the bar. Pause briefly at the top, then lower yourself slowly back down in a controlled manner without fully locking your elbows. Keep your body stable and avoid swinging throughout the movement.', description_i18n: { es: 'Sujeta la barra con agarre supino, palmas hacia ti y manos al ancho de los hombros. Parte desde el colgado con brazos extendidos. Activa el core y tira el pecho hacia la barra flexionando los codos y juntando las escapulas. Sube hasta que el menton pase la barra. Pausa breve arriba y baja lento sin bloquear los codos. Mantiene el cuerpo estable y evita el balanceo.' }, image: require('../assets/workout-api-images/supinated-grip-pull-ups.svg') },
  { id: 'ex-24', name: 'Dips', name_i18n: { es: 'Fondos' }, category: 'Body weight', muscles: {     chest: 0.4,     triceps: 0.4,     shoulders: 0.2 }, description: 'Position yourself between parallel bars, using a step or platform if needed to reach the start. Grab the bars with a neutral grip and fully extend your arms without locking the elbows. Engage your core to maintain stability. Lower your body in a controlled motion by bending your elbows until your upper arms are about parallel to the ground. Avoid letting your elbows go higher than your shoulders. Push back up to the starting position, focusing on your triceps and chest. Keep your body upright and avoid swinging throughout the movement.', description_i18n: { es: 'Colocate entre barras paralelas, usa un escalon si hace falta. Sujeta las barras con agarre neutral y extiende los brazos sin bloquear los codos. Activa el core. Baja el cuerpo de forma controlada flexionando los codos hasta que los brazos superiores queden paralelos al suelo. No subas los codos por encima de los hombros. Empuja para volver a la posicion inicial, enfocando triceps y pecho. Mantiene el cuerpo estable y evita el balanceo.' }, image: require('../assets/workout-api-images/dips.svg') },
  { id: 'ex-25', name: 'Lying Barbell Extensions', name_i18n: { es: 'Extensiones de barra tumbado' }, category: 'Free weight', muscles: {     triceps: 0.8,     chest: 0.2 }, description: 'Sit on a flat bench with a barbell resting on your thighs, gripping it with a narrow overhand grip. Lie back on the bench and extend your arms fully so the barbell is directly above your chest, perpendicular to your torso. Keeping your elbows tucked in and stationary, lower the barbell toward your forehead by bending only at the elbows. Once the bar is close to your forehead, extend your arms back up to the starting position without locking the elbows. Only your forearms should move throughout the exercise.', description_i18n: { es: 'Sientate en un banco plano con la barra sobre los muslos y agarre cerrado pronado. Recuestate y extiende los brazos para colocar la barra sobre el pecho, perpendicular al torso. Manteniendo los codos fijos, baja la barra hacia la frente doblando solo los codos. Cuando la barra este cerca de la frente, extiende los brazos para volver sin bloquear los codos. Solo deben moverse los antebrazos durante el ejercicio.' }, image: require('../assets/workout-api-images/lying-barbell-extensions.svg') },
  { id: 'ex-26', name: 'Close Grip Chest Press', name_i18n: { es: 'Press de pecho con agarre cerrado' }, category: 'Free weight', muscles: {     triceps: 0.8,     shoulders: 0.1,     chest: 0.1 }, description: 'Sit on a flat bench with a barbell resting on your thighs, and grip it with a close overhand grip, palms facing down. Lie back and press the barbell straight up so your arms are fully extended above your chest. Keep your elbows close to your torso and lower the barbell down in a controlled motion until it touches or nearly touches your mid-chest. Press the bar back up to the starting position by extending your arms, without locking your elbows. Focus on keeping tension on the triceps throughout the movement.', description_i18n: { es: 'Sientate en un banco plano con la barra sobre los muslos y agarre cerrado pronado. Recuestate y presiona la barra hacia arriba hasta extender los brazos sobre el pecho. Mantiene los codos cerca del torso y baja la barra con control hasta tocar o casi tocar el pecho medio. Presiona de nuevo para volver sin bloquear los codos. Enfoca la tension en los triceps durante todo el movimiento.' }, image: require('../assets/workout-api-images/close-grip-chest-press.svg') },
  { id: 'ex-27', name: 'Bench Dips', name_i18n: { es: 'Fondos en banco' }, category: 'Body weight', muscles: {     triceps: 0.8,     shoulders: 0.1,     chest: 0.1 }, description: 'Position yourself with your back to a flat bench and place your hands on the edge behind you, fingers pointing forward. Extend your legs in front of you with your heels on the floor and your hips elevated. Lower your body by bending your elbows until your upper arms are about parallel to the ground. Avoid letting your shoulders drop below your elbows. Push yourself back up by extending your arms, without locking the elbows at the top. Engage your core throughout to keep the movement stable.', description_i18n: { es: 'Colocate de espaldas a un banco y apoya las manos en el borde con los dedos hacia adelante. Extiende las piernas al frente con los talones en el suelo y eleva la cadera. Baja el cuerpo doblando los codos hasta que los brazos superiores queden paralelos al suelo. Evita que los hombros bajen mas que los codos. Empuja para volver sin bloquear los codos. Mantiene el core activo para estabilidad.' }, image: require('../assets/workout-api-images/bench-dips.svg') },
  { id: 'ex-28', name: 'Dumbbell Kickback', name_i18n: { es: 'Patada de triceps con mancuerna' }, category: 'Free weight', muscles: {     triceps: 1 }, description: 'Place one knee and the same-side hand on a flat bench for support, keeping your back straight and head in a neutral position. Hold a dumbbell in the opposite hand with your arm bent and upper arm parallel to your torso. Extend your arm fully by straightening the elbow until the dumbbell points backward. Keep your upper arm stationary and close to your body throughout. Squeeze your triceps at the top, then slowly return to the starting position without letting your elbow drop. Perform the desired reps and switch sides.', description_i18n: { es: 'Apoya una rodilla y la mano del mismo lado en un banco, manteniendo la espalda recta y la cabeza neutra. Sujeta una mancuerna con la mano libre, con el codo flexionado y el brazo superior paralelo al torso. Extiende el brazo hasta dejar el codo recto y la mancuerna hacia atras. Mantiene el brazo superior fijo y cerca del cuerpo. Aprieta el triceps arriba y vuelve con control sin dejar caer el codo. Repite y cambia de lado.' }, image: require('../assets/workout-api-images/dumbbell-kickback.svg') },
  { id: 'ex-29', name: 'Dumbbell Overhead Triceps Extension', name_i18n: { es: 'Extension de triceps por encima de la cabeza con mancuerna' }, category: 'Free weight', muscles: {     triceps: 1 }, description: 'Sit on a bench with back support, holding a single dumbbell with both hands. Grip the dumbbell by the upper end with your palms facing the weight plate for stability. Extend your arms overhead, keeping the dumbbell positioned above your head. Slowly bend your elbows to lower the weight behind your head, making sure your upper arms remain stationary and close to your ears. Do not allow the dumbbell to touch your neck. Once you reach a deep stretch, extend your arms again to return to the starting position. Keep your back straight and only move your forearms throughout the exercise.', description_i18n: { es: 'Sientate en un banco con respaldo y sujeta una mancuerna con ambas manos por la parte superior. Extiende los brazos sobre la cabeza con la mancuerna arriba. Flexiona los codos y baja la mancuerna detras de la cabeza, manteniendo los brazos superiores fijos y cerca de las orejas. No dejes que la mancuerna toque el cuello. Cuando sientas el estiramiento, extiende los brazos para volver. Mantiene la espalda recta y mueve solo los antebrazos.' }, image: require('../assets/workout-api-images/dumbbell-overhead-triceps-extension.svg') },
  { id: 'ex-30', name: 'Rope Triceps Extension', name_i18n: { es: 'Extension de triceps con cuerda' }, category: 'Cable', muscles: {     triceps: 1 }, description: 'Attach a rope handle to a high pulley and stand facing the cable machine. Grab the rope with a neutral grip, elbows tucked close to your body and forearms parallel to the floor. Extend your arms downward, pushing the rope toward your thighs while slightly separating the ends of the rope at the bottom of the movement. Contract your triceps at the end, then slowly return to the starting position by bending your elbows. Only your forearms should move during the exercise.', description_i18n: { es: 'Coloca una cuerda en una polea alta y ponte de pie frente a la maquina. Sujeta la cuerda con agarre neutral, codos pegados al cuerpo y antebrazos paralelos al suelo. Extiende los brazos hacia abajo llevando la cuerda a los muslos y separando ligeramente los extremos al final. Contrae los triceps y vuelve lentamente flexionando los codos. Solo deben moverse los antebrazos.' }, image: require('../assets/workout-api-images/rope-triceps-extension.svg') },
  { id: 'ex-31', name: 'Overhead Triceps Extension', name_i18n: { es: 'Extension de triceps por encima de la cabeza' }, category: 'Cable', muscles: {     triceps: 1 }, description: 'Attach a rope handle to a high pulley and stand facing away from the machine. Grab the rope with a neutral grip and bring your hands behind your head with your elbows bent and pointing forward. Take a small step forward and lean slightly. Extend your arms fully in front of you, pushing the rope forward and upward until your arms are straight. Focus on keeping your elbows in position. Slowly return to the starting position by bending your elbows. Keep your back straight and only move your forearms during the exercise.', description_i18n: { es: 'Coloca una cuerda en una polea alta y ponte de espaldas a la maquina. Sujeta la cuerda con agarre neutral y lleva las manos detras de la cabeza con los codos flexionados hacia delante. Da un paso al frente y inclinate ligeramente. Extiende los brazos al frente y arriba hasta dejarlos rectos. Mantiene los codos en posicion. Regresa flexionando los codos. Mantiene la espalda recta y mueve solo los antebrazos.' }, image: require('../assets/workout-api-images/overhead-triceps-extension.svg') },
  { id: 'ex-32', name: 'Close Grip Push-Ups', name_i18n: { es: 'Flexiones con agarre cerrado' }, category: 'Body weight', muscles: {     triceps: 0.8,     shoulders: 0.1,     chest: 0.1 }, description: 'Get into a kneeling position and place your hands on the floor close together, just under your chest. Extend your legs back to form a plank, resting on the balls of your feet. Keep your body straight and engage your core. Lower your chest toward the floor by bending your elbows while keeping them close to your torso. Avoid letting your elbows flare out. Once your chest is just above the ground, push through your palms to return to the starting position. Maintain a straight back and controlled motion throughout.', description_i18n: { es: 'Colocate de rodillas y coloca las manos juntas en el suelo, justo debajo del pecho. Extiende las piernas atras para quedar en plancha apoyado en las puntas de los pies. Mantiene el cuerpo recto y el core activo. Baja el pecho hacia el suelo flexionando los codos y manteniendolos cerca del torso, sin abrirlos. Cuando el pecho quede cerca del suelo, empuja con las palmas para volver a la posicion inicial. Mantiene la espalda recta y el movimiento controlado.' }, image: require('../assets/workout-api-images/close-grip-push-ups.svg') },
  { id: 'ex-33', name: 'Barbell Bench Press', name_i18n: { es: 'Press de banca con barra' }, category: 'Free weight', muscles: {     chest: 0.8,     shoulders: 0.1,     triceps: 0.1 }, description: 'Lie flat on a bench with your feet firmly planted on the floor. Grip the barbell slightly wider than shoulder-width, keeping your wrists aligned over your elbows. Unrack the bar and position it above your chest. Lower the bar under control by bending your elbows, bringing it down to your mid-chest while keeping your elbows at about a 45-degree angle from your torso. Press the bar upward until your arms are extended, without locking your elbows. Maintain symmetry between both arms and avoid excessive arching of your lower back. At the end of your set, carefully rerack the bar.', description_i18n: { es: 'Acuestate en un banco con los pies apoyados en el suelo. Sujeta la barra con un agarre un poco mas ancho que los hombros, con las muñecas alineadas sobre los codos. Desencaja la barra y coloca la barra sobre el pecho. Baja la barra con control hasta el pecho medio, con los codos a unos 45 deg del torso. Empuja hacia arriba hasta extender los brazos sin bloquear los codos. Mantiene el movimiento simetrico y evita arquear demasiado la zona lumbar. Al terminar, vuelve a encajar la barra con cuidado.' }, image: require('../assets/workout-api-images/barbell-bench-press.svg') },
  { id: 'ex-34', name: 'Incline Barbell Bench Press', name_i18n: { es: 'Press de banca inclinado con barra' }, category: 'Free weight', muscles: {     chest: 0.8,     shoulders: 0.1,     triceps: 0.1 }, description: 'Lie back on an incline bench, with your feet firmly planted on the floor. Grip the barbell slightly wider than shoulder-width. Unrack the bar and position it directly above your upper chest. Lower the bar under control by bending your elbows, bringing it to the upper portion of your chest. Press the bar back upward by extending your arms, stopping just before locking your elbows. Keep your back flat against the bench, maintain symmetry, and avoid excessive arching. Rerack the bar safely after completing your set.', description_i18n: { es: 'Acuestate en un banco inclinado con los pies firmes en el suelo. Sujeta la barra un poco mas ancho que los hombros. Desencaja la barra y coloca la barra sobre el pecho superior. Baja la barra con control hasta la parte alta del pecho, flexionando los codos. Empuja la barra hacia arriba hasta casi extender los brazos, sin bloquear los codos. Mantiene la espalda pegada al banco y evita arquear en exceso. Encaja la barra al terminar.' }, image: require('../assets/workout-api-images/incline-barbell-bench-press.svg') },
  { id: 'ex-35', name: 'Decline Barbell Bench Press', name_i18n: { es: 'Press de banca declinado con barra' }, category: 'Free weight', muscles: {     chest: 0.8,     shoulders: 0.1,     triceps: 0.1 }, description: 'Lie back on a decline bench with your feet secured under the foot pads and your back firmly supported. Grip the barbell slightly wider than shoulder-width. Unrack the bar and position it over your lower chest. Lower the bar slowly and under control by bending your elbows, keeping them at a slight angle from your torso. Press the bar back up by extending your arms until they are almost straight, without locking the elbows. Focus on maintaining symmetry, keeping your back stable, and returning the bar safely to the rack after your set.', description_i18n: { es: 'Acuestate en un banco declinado con los pies asegurados. Sujeta la barra un poco mas ancho que los hombros. Desencaja la barra y coloca la barra sobre el pecho inferior. Baja la barra con control flexionando los codos, sin abrirlos demasiado. Empuja la barra hacia arriba hasta casi extender los brazos, sin bloquear los codos. Mantiene la espalda estable y devuelve la barra al soporte al terminar.' }, image: require('../assets/workout-api-images/decline-barbell-bench-press.svg') },
  { id: 'ex-36', name: 'Dumbbell Bench Press', name_i18n: { es: 'Press de banca con mancuernas' }, category: 'Free weight', muscles: {     chest: 0.8,     shoulders: 0.1,     triceps: 0.1 }, description: 'Sit on a flat bench with a dumbbell in each hand, using a neutral or standard grip. Lie back with your feet firmly planted on the floor and bring the dumbbells to chest level. Press the weights upward until your arms are nearly extended, allowing the dumbbells to come close together at the top. Lower the dumbbells under control by bending your elbows, bringing them down to the sides of your chest according to your shoulder mobility. Press back up while keeping your arms moving in a controlled arc. Do not lock out the elbows. Keep your back flat on the bench and ensure even movement on both sides.', description_i18n: { es: 'Sientate en un banco plano con una mancuerna en cada mano y recuestate. Lleva las mancuernas a la altura del pecho. Presiona hacia arriba hasta casi extender los brazos, juntando ligeramente las mancuernas arriba. Baja con control flexionando los codos hasta que queden a la altura del pecho. No bloquees los codos. Mantiene la espalda pegada al banco y el movimiento parejo.' }, image: require('../assets/workout-api-images/dumbbell-bench-press.svg') },
  { id: 'ex-37', name: 'Incline Dumbbell Bench Press', name_i18n: { es: 'Press inclinado con mancuernas' }, category: 'Free weight', muscles: {     chest: 0.8,     shoulders: 0.1,     triceps: 0.1 }, description: 'Sit on an incline bench with a dumbbell in each hand, using a neutral or standard grip. Lie back with your feet firmly planted on the floor and position the dumbbells at chest level. Press the dumbbells upward at a slight angle until your arms are almost fully extended, bringing the weights close together at the top. Slowly lower them under control by bending your elbows, allowing the dumbbells to descend toward the upper chest. Avoid locking your elbows at the top and maintain control throughout the motion. Keep your back pressed to the bench and ensure symmetrical movement with both arms.', description_i18n: { es: 'Sientate en un banco inclinado con una mancuerna en cada mano. Recuestate y coloca las mancuernas a la altura del pecho. Presiona hacia arriba en un angulo ligeramente diagonal hasta casi extender los brazos, sin bloquear los codos. Baja con control hacia la parte alta del pecho. Mantiene la espalda pegada al banco y el movimiento simetrico.' }, image: require('../assets/workout-api-images/incline-dumbbell-bench-press.svg') },
  { id: 'ex-38', name: 'Decline Dumbbell Bench Press', name_i18n: { es: 'Press declinado con mancuernas' }, category: 'Free weight', muscles: {     chest: 0.8,     shoulders: 0.1,     triceps: 0.1 }, description: 'Sit on a decline bench with a dumbbell in each hand using a neutral or standard grip. Lie back and secure your feet under the support pads. Bring the dumbbells to chest level and press them upward until your arms are nearly extended, bringing the weights close together at the top. Slowly lower the dumbbells in a controlled arc toward the lower chest by bending your elbows. Avoid locking your elbows at the top. Maintain control and symmetry between both arms, keep your back supported on the bench, and avoid excessive arching.', description_i18n: { es: 'Sientate en un banco declinado con una mancuerna en cada mano y asegura los pies. Recuestate y lleva las mancuernas al pecho. Presiona hacia arriba hasta casi extender los brazos, acercando ligeramente las mancuernas arriba. Baja con control hacia el pecho inferior, sin bloquear los codos. Mantiene la espalda estable y el movimiento parejo.' }, image: require('../assets/workout-api-images/decline-dumbbell-bench-press.svg') },
  { id: 'ex-39', name: 'Dumbbell Chest Flys', name_i18n: { es: 'Aperturas de pecho con mancuernas' }, category: 'Free weight', muscles: {     chest: 0.8,     shoulders: 0.2 }, description: 'Sit on a flat bench with a dumbbell in each hand using a neutral grip. Lie back with your feet firmly planted on the ground and extend your arms above your chest with the dumbbells close together. Open your arms out to the sides in a wide arc, keeping a slight bend in your elbows. Lower the dumbbells until they reach approximately chest level, depending on your shoulder mobility. Engage your chest to bring the dumbbells back together over your chest in a controlled motion. Avoid locking the elbows. To emphasize the upper chest, you can use a slightly inclined bench, but too much incline will shift the focus to the shoulders.', description_i18n: { es: 'Acuestate en un banco plano con una mancuerna en cada mano. Extiende los brazos sobre el pecho con una ligera flexion de codos. Abre los brazos en un arco amplio hacia los lados hasta que las mancuernas queden a la altura del pecho, segun tu movilidad. Contrae el pecho para volver a juntar las mancuernas arriba. Mantiene los codos ligeramente flexionados y no los bloquees.' }, image: require('../assets/workout-api-images/dumbbell-chest-flys.svg') },
  { id: 'ex-40', name: 'Push-Ups', name_i18n: { es: 'Flexiones' }, category: 'Body weight', muscles: {     chest: 0.8,     shoulders: 0.1,     triceps: 0.1 }, description: 'Start on all fours, placing your hands shoulder-width apart or slightly wider, and your feet extended behind you with your toes on the ground. Keep your body in a straight line from head to heels by engaging your core and glutes. Lower your chest toward the floor by bending your elbows, keeping them close to your sides. When your chest nearly touches the floor, push through your palms to extend your arms and return to the starting position. Maintain a straight spine and avoid letting your hips sag or rise throughout the movement.', description_i18n: { es: 'Colocate en plancha con las manos al ancho de los hombros o un poco mas. Mantiene el cuerpo en linea recta de cabeza a talones, con core y gluteos activos. Baja el pecho hacia el suelo flexionando los codos, manteniendolos cerca del torso. Cuando el pecho quede cerca del suelo, empuja con las palmas para volver arriba. Mantiene la columna neutra y evita que la cadera se hunda o suba demasiado.' }, image: require('../assets/workout-api-images/push-ups.svg') },
  { id: 'ex-41', name: 'Pec-Deck / Butterfly', name_i18n: { es: 'Pec-deck / mariposa' }, category: 'Machine', muscles: {     chest: 1 }, description: 'Adjust the seat so that your elbows are aligned with shoulder height when you grip the handles. Sit with your back firmly against the pad and your feet flat on the floor. Keep a slight bend in your elbows and bring the handles together in front of your chest by contracting your chest muscles. Pause briefly at the top, then slowly return to the starting position by opening your arms in a controlled motion. Keep the movement smooth and your back supported throughout the exercise.', description_i18n: { es: 'Ajusta el asiento para que los codos queden a la altura de los hombros al sujetar las manijas. Sientate con la espalda pegada al respaldo y los pies en el suelo. Con ligera flexion de codos, junta las manijas frente al pecho contrayendo el pectoral. Pausa breve y regresa abriendo los brazos con control. Mantiene el movimiento suave y la espalda apoyada.' }, image: require('../assets/workout-api-images/pec-deck-butterfly.svg') },
  { id: 'ex-42', name: 'Seated Chest Press', name_i18n: { es: 'Press de pecho sentado' }, category: 'Machine', muscles: {     chest: 0.8,     shoulders: 0.1,     triceps: 0.1 }, description: 'Adjust the seat so that the handles are aligned with the middle of your chest. Sit down with your back flat against the pad and feet firmly on the floor. Grasp the handles with elbows bent around 90 degrees. Press the handles forward by extending your arms in a controlled motion, without locking your elbows at the top. Slowly return to the starting position by bending your elbows, keeping tension on your chest muscles throughout the movement.', description_i18n: { es: 'Ajusta el asiento para que las manijas queden a la altura del pecho. Sientate con la espalda pegada al respaldo y los pies firmes. Sujeta las manijas con codos flexionados cerca de 90 deg. Empuja hacia adelante hasta casi extender los brazos, sin bloquear los codos. Vuelve con control a la posicion inicial manteniendo tension en el pecho.' }, image: require('../assets/workout-api-images/seated-chest-press.svg') },
  { id: 'ex-43', name: 'High Cable Chest Fly', name_i18n: { es: 'Aperturas de pecho en cable alto' }, category: 'Cable', muscles: {     chest: 1 }, description: 'Set the pulleys to a high position and stand in the center of the machine. Grab the handles with a neutral grip and take a small step forward to create tension. With a slight bend in your elbows, open your arms wide, then bring your hands together in front of your chest by contracting your pectorals. Keep the movement slow and controlled, especially during the negative phase. Do not let the handles go too far behind you to avoid shoulder strain. You can lean slightly forward to better isolate specific areas of the chest.', description_i18n: { es: 'Ajusta las poleas en posicion alta y colocate en el centro. Sujeta las manijas con agarre neutral y da un paso al frente para crear tension. Con ligera flexion de codos, abre los brazos y luego junta las manos frente al pecho contrayendo el pectoral. Mantiene el movimiento lento y controlado, sobre todo al regresar. No dejes que las manijas se vayan demasiado atras.' }, image: require('../assets/workout-api-images/high-cable-chest-fly.svg') },
  { id: 'ex-44', name: 'Low Cable Chest Fly', name_i18n: { es: 'Aperturas de pecho en cable bajo' }, category: 'Cable', muscles: {     chest: 0.8,     shoulders: 0.2 }, description: 'Set the pulleys to a low position and stand in the center of the machine. Grab the handles with a neutral grip and step slightly forward to create tension. With a slight bend in your elbows, raise your arms upward in a wide arc while bringing your hands together in front of your head, contracting your chest muscles. Pause briefly at the top, then slowly lower your arms back to the starting position in a controlled motion. Focus on keeping your chest engaged throughout the movement.', description_i18n: { es: 'Ajusta las poleas en posicion baja y colocate en el centro. Sujeta las manijas con agarre neutral y da un paso al frente para crear tension. Con ligera flexion de codos, eleva los brazos en un arco amplio hasta juntar las manos frente a la cabeza. Pausa breve arriba y vuelve con control. Mantiene el pecho activo durante todo el movimiento.' }, image: require('../assets/workout-api-images/low-cable-chest-fly.svg') },
  { id: 'ex-45', name: 'Incline Chest Press Machine', name_i18n: { es: 'Press de pecho inclinado en maquina' }, category: 'Machine', muscles: {     chest: 0.8,     shoulders: 0.1,     triceps: 0.1 }, description: 'Adjust the seat height so the handles align with your upper chest. Sit with your back firmly against the pad and feet flat on the floor. Grasp the handles with a firm grip and press them upward and slightly forward by extending your arms, without locking your elbows at the top. Slowly bring the handles back down in a controlled motion to return to the starting position. Keep your chest engaged and back supported throughout the movement.', description_i18n: { es: 'Ajusta el asiento para que las manijas queden a la altura del pecho superior. Sientate con la espalda pegada al respaldo y los pies firmes. Sujeta las manijas y empuja hacia arriba y adelante hasta casi extender los brazos, sin bloquear los codos. Baja con control a la posicion inicial. Mantiene el pecho activo y la espalda apoyada.' }, image: require('../assets/workout-api-images/incline-chest-press-machine.svg') },
  { id: 'ex-46', name: 'Pronated Grip Pull-Ups', name_i18n: { es: 'Dominadas pronadas' }, category: 'Body weight', muscles: {     lats: 0.6,     midBack: 0.2,     shoulders: 0.1,     biceps: 0.1 }, description: 'Grab the pull-up bar with an overhand (pronated) grip, hands at or slightly wider than shoulder-width apart. Engage your back muscles and pull your body upward until your chin passes the height of the bar. Focus on keeping the movement smooth and controlled. Slowly lower yourself back down without fully locking your elbows at the bottom. Keep your body tight and avoid swinging. Emphasize pulling with your back rather than relying too much on the biceps, especially in the early phase of the lift.', description_i18n: { es: 'Sujeta la barra con agarre pronado, manos al ancho de los hombros o un poco mas. Activa la espalda y sube el cuerpo hasta que el menton pase la barra. Mantiene el movimiento controlado. Baja lentamente sin bloquear del todo los codos. Mantiene el cuerpo firme y evita el balanceo.' }, image: require('../assets/workout-api-images/pronated-grip-pull-ups.svg') },
  { id: 'ex-47', name: 'Horizontal Row Machine', name_i18n: { es: 'Remo horizontal en maquina' }, category: 'Machine', muscles: {     lats: 0.4,     midBack: 0.3,     biceps: 0.15,     shoulders: 0.1,     traps: 0.05 }, description: 'Sit facing the machine and place your feet on the supports. Bend your knees to reach the handles while keeping your back straight. Then extend your legs slightly to unlock the weight stack and create space. Retract your shoulders and squeeze your shoulder blades together as you pull the handles toward your midsection, ideally around your navel. Slowly return to the starting position with control. After completing your repetitions, bend your knees again to bring the weight stack back without rounding your back.', description_i18n: { es: 'Sientate en la maquina y coloca los pies en los apoyos. Flexiona las rodillas para tomar las manijas y luego extiende un poco las piernas para liberar el peso. Retrae los hombros y tira de las manijas hacia el abdomen, apretando las escapulas. Vuelve con control a la posicion inicial. Al terminar, flexiona las rodillas para apoyar el peso sin redondear la espalda.' }, image: require('../assets/workout-api-images/horizontal-row-machine.svg') },
  { id: 'ex-48', name: 'Pull-Down', name_i18n: { es: 'Jalon al pecho' }, category: 'Machine', muscles: {     lats: 0.7,     midBack: 0.1,     shoulders: 0.1,     biceps: 0.1 }, description: 'Sit on the seat facing the machine and grasp the bar with a pronated grip (palms facing away), hands shoulder-width or slightly wider. Engage your lats to pull the bar down toward your upper chest, keeping your torso upright. Pause briefly at the bottom, then slowly return to the starting position without locking out your elbows. Focus on controlling the negative phase of the movement. This exercise can also be performed with a supinated grip (palms facing you) for increased biceps activation.', description_i18n: { es: 'Sientate frente a la maquina y sujeta la barra con agarre pronado, manos al ancho de los hombros o un poco mas. Tira la barra hacia el pecho superior manteniendo el torso erguido. Pausa breve abajo y regresa lentamente sin bloquear los codos. Controla la fase negativa. Puedes usar agarre supino para mayor trabajo de biceps.' }, image: require('../assets/workout-api-images/pull-down.svg') },
  { id: 'ex-49', name: 'Barbell Bent Over Row', name_i18n: { es: 'Remo con barra inclinado' }, category: 'Free weight', muscles: {     lats: 0.35,     midBack: 0.35,     traps: 0.1,     biceps: 0.1,     shoulders: 0.1 }, description: 'Stand with your feet shoulder-width apart and grasp the barbell with a pronated grip (palms facing down), holding it at hip level. Bend forward at the hips, keeping your back straight and chest up. Pull the bar toward your lower abdomen by retracting your shoulders and squeezing your shoulder blades together. Lower the bar in a controlled manner back to the starting position. Maintain a straight back throughout the movement. This exercise can also be performed with a supinated grip (palms facing up) to place more emphasis on the biceps.', description_i18n: { es: 'De pie con los pies al ancho de los hombros, sujeta la barra con agarre pronado a la altura de la cadera. Inclina el torso desde las caderas con espalda recta y pecho arriba. Tira la barra hacia el abdomen bajo retrayendo los hombros y apretando las escapulas. Baja la barra con control. Mantiene la espalda recta todo el tiempo.' }, image: require('../assets/workout-api-images/barbell-bent-over-row.svg') },
  { id: 'ex-50', name: 'Bent Over Dumbbell Row', name_i18n: { es: 'Remo con mancuernas inclinado' }, category: 'Free weight', muscles: {     lats: 0.35,     midBack: 0.35,     traps: 0.1,     shoulders: 0.1,     biceps: 0.1 }, description: 'Stand with a dumbbell in each hand, arms hanging at your sides. Slightly bend your knees and hinge forward at the hips while keeping your back straight and chest up. Pull the dumbbells toward your hips by retracting your shoulders and squeezing your shoulder blades together. Lower the weights in a controlled motion until your arms are nearly fully extended. Focus on using your back muscles and minimize biceps involvement to better isolate the upper and mid-back.', description_i18n: { es: 'De pie con una mancuerna en cada mano, flexiona ligeramente las rodillas e inclina el torso con la espalda recta. Tira de las mancuernas hacia las caderas retrayendo los hombros y apretando las escapulas. Baja con control hasta casi extender los brazos. Enfoca el trabajo en la espalda y reduce la ayuda de los biceps.' }, image: require('../assets/workout-api-images/bent-over-dumbbell-row.svg') },
  { id: 'ex-51', name: 'Unilateral Bent Over Row', name_i18n: { es: 'Remo inclinado unilateral' }, category: 'Free weight', muscles: {     lats: 0.35,     midBack: 0.35,     traps: 0.1,     shoulders: 0.1,     biceps: 0.1 }, description: 'Place one knee and the same-side hand on a flat bench to support your body, ensuring your back remains flat and parallel to the ground. With your free hand, grab a dumbbell and pull it up toward your hip by retracting your shoulder and squeezing your shoulder blade. Pause briefly at the top, then lower the dumbbell under control until your arm is nearly fully extended. Focus on using your back muscles rather than the biceps. After completing one side, switch and perform the movement on the other arm.', description_i18n: { es: 'Apoya una rodilla y la mano del mismo lado en un banco para estabilizar el cuerpo, con la espalda recta y paralela al suelo. Con la mano libre, tira de la mancuerna hacia la cadera retrayendo el hombro y apretando la escapula. Pausa breve arriba y baja con control hasta casi extender el brazo. Cambia de lado al terminar.' }, image: require('../assets/workout-api-images/unilateral-bent-over-row.svg') },
  { id: 'ex-52', name: 'Australian Pull-Ups', name_i18n: { es: 'Dominadas australianas' }, category: 'Body weight', muscles: {     lats: 0.5,     midBack: 0.2,     shoulders: 0.1,     biceps: 0.1,     forearms: 0.1 }, description: 'Set the bar at a height that allows you to grip it while keeping your heels on the ground. Grab the bar with an overhand grip (palms facing away from you), hands shoulder-width apart or slightly wider. Engage your shoulder blades to pull your chest toward the bar while keeping your body straight and core tight. Lower yourself in a controlled manner without locking out the elbows at the bottom. Focus on using your back muscles throughout the movement and avoid relying on the biceps too early in the pull.', description_i18n: { es: 'Coloca la barra a una altura que te permita sujetarla con los talones en el suelo. Toma la barra con agarre pronado y manos al ancho de los hombros. Tira del pecho hacia la barra manteniendo el cuerpo recto y el core activo. Baja con control sin bloquear los codos. Enfoca el esfuerzo en la espalda y evita tirar con los biceps al inicio.' }, image: require('../assets/workout-api-images/australian-pull-ups.svg') },
  { id: 'ex-53', name: 'T-Bar Row', name_i18n: { es: 'Remo con barra T' }, category: 'Free weight', muscles: {     lats: 0.4,     midBack: 0.3,     shoulders: 0.1,     biceps: 0.1,     traps: 0.1 }, description: 'Stand over the T-bar with your feet shoulder-width apart. Bend your knees slightly and hinge forward at the hips while keeping your back flat and chest up. Grab the handles with either a pronated or neutral grip, depending on the handle type. Pull the bar toward your torso by retracting your shoulder blades and driving your elbows back. Squeeze your back at the top, then lower the weight under control without locking your arms at the bottom. Focus on using your back muscles and limit biceps involvement early in the pull.', description_i18n: { es: 'Colocate sobre la barra T con los pies al ancho de los hombros. Flexiona ligeramente las rodillas e inclina el torso con la espalda recta. Sujeta las manijas con agarre pronado o neutral segun el accesorio. Tira hacia el torso retrayendo las escapulas y llevando los codos atras. Aprieta la espalda arriba y baja con control sin bloquear los brazos.' }, image: require('../assets/workout-api-images/t-bar-row.svg') },
  { id: 'ex-54', name: 'Deadlift', name_i18n: { es: 'Peso muerto' }, category: 'Free weight', muscles: {     glutes: 0.35,     hamstrings: 0.25,     midBack: 0.15,     lats: 0.1,     traps: 0.05,     forearms: 0.1 }, description: 'Stand with your feet shoulder-width apart, the barbell positioned over the middle of your feet. Bend at the hips and knees while keeping your back flat and chest up. Grab the bar with a pronated grip (palms facing you) and engage your lats by pulling your shoulders back. Push through your heels to lift the bar, extending your hips and knees simultaneously until you\'re standing upright. Pause briefly at the top without leaning back. Lower the bar in a controlled motion by hinging at the hips and bending your knees, keeping your back straight throughout the descent.', description_i18n: { es: 'Coloca la barra sobre la mitad de los pies. Flexiona caderas y rodillas con la espalda recta y el pecho arriba, y sujeta la barra con agarre pronado. Activa los dorsales y empuja con los talones para levantar la barra extendiendo caderas y rodillas a la vez hasta quedar de pie. Pausa breve arriba sin hiperextender. Baja la barra con control llevando las caderas atras y flexionando las rodillas.' }, image: require('../assets/workout-api-images/deadlift.svg') },
  { id: 'ex-55', name: 'Back extensions', name_i18n: { es: 'Extensiones de espalda' }, category: 'Machine', muscles: {     midBack: 0.5,     glutes: 0.25,     hamstrings: 0.25 }, description: 'Position yourself on the back extension machine, securing your feet and adjusting the pad so it rests just below your hips. Start with your upper body straight in line with your legs. Lower your torso by hinging at the hips, keeping your back flat and descending as far as your mobility allows. Reverse the movement by contracting your lower back muscles to raise your torso until your body is straight again, avoiding hyperextension. To increase difficulty, you can hold a weight plate against your chest.', description_i18n: { es: 'Colocate en la maquina de extensiones y ajusta el pad para que quede debajo de las caderas. Comienza con el torso alineado con las piernas. Baja el torso flexionando la cadera con la espalda recta hasta donde tu movilidad permita. Sube contrayendo la zona lumbar hasta volver a la linea recta, sin hiperextender. Puedes sostener un disco para aumentar la dificultad.' }, image: require('../assets/workout-api-images/back-extensions.svg') },
  { id: 'ex-56', name: 'Pushdown straight arm', name_i18n: { es: 'Jalon de brazos rectos' }, category: 'Cable', muscles: {     lats: 0.65,     midBack: 0.15,     traps: 0.05,     shoulders: 0.05,     triceps: 0.1 }, description: 'Stand facing the cable machine and grab the straight bar with a pronated grip (palms facing down). Step slightly back and bend your knees slightly while keeping your back straight. With arms fully extended but not locked, use your lats to push the bar down toward your thighs, maintaining your arms straight throughout the motion. Once at the bottom, slowly return the bar to the starting position in a controlled manner. Keep your back straight and core engaged at all times.', description_i18n: { es: 'De pie frente a la polea, sujeta la barra recta con agarre pronado. Da un paso atras y flexiona ligeramente las rodillas con la espalda recta. Con los brazos extendidos y sin bloquear los codos, empuja la barra hacia los muslos usando los dorsales. Vuelve con control a la posicion inicial manteniendo los brazos rectos. Mantiene el core activo.' }, image: require('../assets/workout-api-images/pushdown-straight-arm.svg') },
  { id: 'ex-57', name: 'Low cable row', name_i18n: { es: 'Remo en cable bajo' }, category: 'Machine', muscles: {     lats: 0.4,     midBack: 0.3,     shoulders: 0.1,     biceps: 0.15,     traps: 0.05 }, description: 'Stand or sit facing the low pulley machine and grab the handle with a pronated grip (palms facing down). Keep your back straight and chest up as you pull the handle toward your torso, focusing on squeezing your shoulder blades together. Pause briefly at the top, then slowly return to the starting position with control. You may also perform this exercise with a supinated grip (palms facing up) for more biceps engagement, or unilaterally to isolate each side.', description_i18n: { es: 'Sientate frente a la polea baja y sujeta la manija con agarre pronado. Mantiene la espalda recta y el pecho arriba. Tira de la manija hacia el torso apretando las escapulas. Pausa breve y vuelve con control. Puedes usar agarre supino o hacerlo unilateral para variar el trabajo.' }, image: require('../assets/workout-api-images/low-cable-row.svg') },
  { id: 'ex-58', name: 'TRX row', name_i18n: { es: 'Remo en TRX' }, category: 'Body weight', muscles: {     lats: 0.45,     midBack: 0.25,     shoulders: 0.1,     biceps: 0.1,     forearms: 0.1 }, description: 'Grab the two handles with a neutral grip and lean back while keeping your arms and legs extended but not locked. Pull your chest toward the handles by bending your elbows and keeping them close to your body. Control the descent back to the starting position. Maintain a straight body line throughout the movement. You can increase or decrease the difficulty by adjusting your foot placement and the height of the handles. Changing your grip (pronated or supinated) also helps target different muscle fibers.', description_i18n: { es: 'Sujeta las manijas con agarre neutral y reclinate hacia atras con brazos y piernas extendidos sin bloquear. Tira del pecho hacia las manijas flexionando los codos y manteniendolos cerca del cuerpo. Controla el descenso a la posicion inicial. Mantiene el cuerpo en linea recta. Ajusta la dificultad con la posicion de los pies y la altura de las manijas.' }, image: require('../assets/workout-api-images/trx-row.svg') },
  { id: 'ex-59', name: 'Pullover', name_i18n: { es: 'Pullover' }, category: 'Free weight', muscles: {     lats: 0.7,     midBack: 0.1,     chest: 0.2 }, description: 'Place a dumbbell on your knees while sitting on the bench. Lie back and bring the dumbbell above your chest, holding it with both palms against the inside of the weight plate for better control. Extend your arms slightly bent and pivot the shoulders backward to lower the dumbbell behind your head. Engage your lats to bring the weight back above your chest and repeat. Maintain a strong grip on the weight to avoid injury. This exercise can also be performed with a barbell.', description_i18n: { es: 'Sientate en un banco con una mancuerna sobre las rodillas. Recuestate y lleva la mancuerna sobre el pecho, sujetandola con ambas manos por la placa. Con los brazos ligeramente flexionados, baja la mancuerna detras de la cabeza desde los hombros. Activa los dorsales para regresar la mancuerna arriba. Mantiene el agarre firme y evita arquear la espalda.' }, image: require('../assets/workout-api-images/pullover.svg') },
  { id: 'ex-60', name: 'Crunches', name_i18n: { es: 'Encogimientos abdominales' }, category: 'Body weight', muscles: {     abs: 0.8,     obliques: 0.2 }, description: 'Lie on your back on a mat with your knees bent. Place your hands at your temples or cross your arms over your chest. Contract your abdominal muscles to lift your upper body off the floor, keeping your lower back pressed against the mat at all times. Return to the starting position and repeat.', description_i18n: { es: 'Acuestate en una colchoneta con las rodillas flexionadas. Coloca las manos en las sienes o cruza los brazos sobre el pecho. Contrae el abdomen para elevar el torso manteniendo la zona lumbar pegada al suelo. Vuelve a la posicion inicial y repite.' }, image: require('../assets/workout-api-images/crunches.svg') },
  { id: 'ex-61', name: 'Rotation crunches', name_i18n: { es: 'Encogimientos con rotacion' }, category: 'Body weight', muscles: {     abs: 0.5,     obliques: 0.5 }, description: 'Lie on your back on a mat with your knees bent. Place your hands at your temples and cross one leg over the other by placing your ankle on the opposite knee. Contract your abs while slightly rotating your torso to bring your elbow toward the crossed leg. Return to the starting position and repeat with the opposite leg. Keep your lower back pressed against the mat throughout the exercise.', description_i18n: { es: 'Acuestate en una colchoneta con las rodillas flexionadas. Coloca las manos en las sienes y cruza un tobillo sobre la rodilla contraria. Contrae el abdomen mientras rotas el torso para llevar el codo hacia la pierna cruzada. Vuelve a la posicion inicial y repite con la otra pierna. Mantiene la zona lumbar pegada al suelo.' }, image: require('../assets/workout-api-images/rotation-crunches.svg') },
  { id: 'ex-62', name: 'Leg raises', name_i18n: { es: 'Elevaciones de piernas' }, category: 'Body weight', muscles: {     abs: 0.8,     obliques: 0.2 }, description: 'Lie on your back on a mat with your arms at your sides and your legs straight or slightly bent. Contract your abs to lift your legs up to about a 90 deg angle, then control the descent back to the starting position, stopping just before your feet touch the ground to maximize muscle engagement. Keep your lower back pressed against the mat throughout the exercise.', description_i18n: { es: 'Acuestate en una colchoneta con los brazos a los lados y las piernas extendidas o ligeramente flexionadas. Contrae el abdomen para elevar las piernas hasta unos 90 deg, luego baja con control sin dejar que los pies toquen el suelo. Mantiene la zona lumbar pegada a la colchoneta durante todo el movimiento.' }, image: require('../assets/workout-api-images/leg-raises.svg') },
  { id: 'ex-63', name: 'Plank', name_i18n: { es: 'Plancha' }, category: 'Body weight', muscles: {     abs: 0.8,     shoulders: 0.1,     obliques: 0.1 }, description: 'Kneel down, then place your elbows on the mat and extend your legs to distribute your weight between your toes and forearms. Your back should remain straight throughout the hold. Contract your abs to maintain this position for the set duration, then relax.', description_i18n: { es: 'Arrodillate y apoya los codos en la colchoneta, luego extiende las piernas para repartir el peso entre antebrazos y puntas de los pies. Mantiene la espalda recta durante todo el tiempo. Contrae el abdomen para sostener la posicion por el tiempo indicado y luego relaja.' }, image: require('../assets/workout-api-images/plank.svg') },
  { id: 'ex-64', name: 'Lateral plank', name_i18n: { es: 'Plancha lateral' }, category: 'Body weight', muscles: {     obliques: 0.8,     shoulders: 0.1,     abs: 0.1 }, description: 'Kneel down and place one of your elbows on the mat, then extend your legs on the opposite side to distribute your weight between one foot and the active forearm. You will be positioned sideways to engage the oblique muscle. Your back should remain straight throughout the hold. Contract your abs to maintain this position for the set duration, then relax. Repeat on the other side.', description_i18n: { es: 'Arrodillate y apoya un codo en la colchoneta, luego extiende las piernas hacia el lado opuesto para repartir el peso entre el pie y el antebrazo activo. Quedas de lado para trabajar el oblicuo. Mantiene la espalda recta. Contrae el abdomen y sosten la posicion el tiempo indicado, luego cambia de lado.' }, image: require('../assets/workout-api-images/lateral-plank.svg') },
  { id: 'ex-65', name: 'Mountain climbers', name_i18n: { es: 'Escaladores' }, category: 'Body weight', muscles: {     abs: 0.8,     obliques: 0.2 }, description: 'Kneel down and place your hands flat on the mat, then extend your legs. Bend one knee to bring it toward your chest. At that moment, extend that same leg back to the starting position while bending the opposite knee. Repeat this cycle at a fast pace to work on your cardio. Remember to contract your abs throughout the movement.', description_i18n: { es: 'Colocate en plancha con las manos en la colchoneta y las piernas extendidas. Lleva una rodilla hacia el pecho. En ese momento, extiende esa pierna y trae la otra rodilla. Repite el ciclo a un ritmo rapido para trabajar cardio. Mantiene el abdomen contraido durante todo el movimiento.' }, image: require('../assets/workout-api-images/mountain-climbers.svg') },
  { id: 'ex-66', name: 'Russian twist', name_i18n: { es: 'Giros rusos' }, category: 'Body weight', muscles: {     abs: 0.5,     obliques: 0.5 }, description: 'Sit on a mat with your knees bent and your hands joined in front of you. Slightly lift both feet off the floor, and rotate your torso to bring your hands to one side of your body while keeping them together. Do the same on the opposite side and continue. Keep your abs engaged to optimize core work and maintain posture and balance.', description_i18n: { es: 'Sientate en la colchoneta con las rodillas flexionadas y las manos juntas al frente. Eleva ligeramente los pies del suelo y rota el torso para llevar las manos hacia un lado del cuerpo. Repite hacia el otro lado de forma continua. Mantiene el abdomen activo y la espalda estable.' }, image: require('../assets/workout-api-images/russian-twist.svg') },
  { id: 'ex-67', name: 'V-ups', name_i18n: { es: 'Abdominales en V' }, category: 'Body weight', muscles: {     abs: 0.8,     obliques: 0.2 }, description: 'Lie down on a mat with your legs together and your arms by your sides. Contract your abs to raise your legs while keeping them straight, and lift your torso to try to touch your feet with your hands. The goal is to balance on your glutes during each repetition.', description_i18n: { es: 'Acuestate en la colchoneta con las piernas juntas y los brazos a los lados. Contrae el abdomen para elevar las piernas rectas y el torso, intentando tocar los pies con las manos. El objetivo es equilibrarte sobre los gluteos en cada repeticion.' }, image: require('../assets/workout-api-images/v-ups.svg') },
  { id: 'ex-68', name: 'Scissors', name_i18n: { es: 'Tijeras' }, category: 'Body weight', muscles: {     abs: 0.8,     obliques: 0.2 }, description: 'Lie down on a mat with your legs together and your arms along your sides. Slightly lift both legs off the ground, then raise one leg while keeping it straight, as the other remains close to the floor. Lower the raised leg while lifting the other, and alternate like this throughout the set. Keep your lower back pressed into the mat during the entire movement.', description_i18n: { es: 'Acuestate en la colchoneta con las piernas juntas y los brazos a los lados. Eleva ligeramente ambas piernas, luego sube una pierna recta mientras la otra queda cerca del suelo. Baja esa pierna y sube la otra, alternando durante toda la serie. Mantiene la zona lumbar pegada a la colchoneta.' }, image: require('../assets/workout-api-images/scissors.svg') },
  { id: 'ex-69', name: 'Roman chair leg raises', name_i18n: { es: 'Elevaciones de piernas en silla romana' }, category: 'Body weight', muscles: {     abs: 0.8,     obliques: 0.2 }, description: 'Press your back against the pad and place your elbows on the armrests so that your arms are bent at 90 deg. With legs straight and together, bend them to raise your knees as high as possible, contracting your abs throughout the movement. While maintaining this contraction, return to the starting position with legs extended, and repeat. This exercise can also be performed with legs kept straight the entire time, which makes it harder and more effective. Always keep your back pressed against the pad during execution.', description_i18n: { es: 'Apoya la espalda en el respaldo y coloca los codos en los apoyos para que queden a 90 deg. Con las piernas rectas y juntas, elevalas para llevar las rodillas lo mas alto posible, contrayendo el abdomen. Manteniendo la contraccion, vuelve a la posicion inicial con las piernas extendidas y repite. Tambien puedes hacerlo con las piernas rectas todo el tiempo para mayor dificultad. Mantiene la espalda pegada al respaldo.' }, image: require('../assets/workout-api-images/roman-chair-leg-raises.svg') },
  { id: 'ex-70', name: 'Heel touches', name_i18n: { es: 'Toques de talon' }, category: 'Body weight', muscles: {     obliques: 0.8,     abs: 0.2 }, description: 'Lie on a mat with your knees bent and arms along your sides. By contracting your obliques, reach to touch your heel on one side with your hand, without lifting your back off the mat. Return to the starting position and repeat on the other side. Keep your abs contracted throughout the movement to maximize muscle engagement.', description_i18n: { es: 'Acuestate en la colchoneta con las rodillas flexionadas y los brazos a los lados. Contrayendo los oblicuos, inclina el torso para tocar el talon de un lado con la mano sin despegar la espalda del suelo. Vuelve al centro y repite hacia el otro lado. Mantiene el abdomen contraido.' }, image: require('../assets/workout-api-images/heel-touches.svg') },
  { id: 'ex-71', name: 'Cable crunches', name_i18n: { es: 'Crunches en cable' }, category: 'Cable', muscles: {     abs: 0.8,     obliques: 0.2 }, description: 'Attach a rope to a high pulley and kneel facing it. Grab the rope with both hands in a neutral grip (palms facing inward), keeping your back straight at the start. Contract your abs to round your back forward, keeping the ends of the rope near your ears. Once you\'ve reached maximum contraction, return to the starting position slowly to optimize muscle engagement. Avoid going too low to prevent engaging the hip flexors and focus on the abs.', description_i18n: { es: 'Coloca una cuerda en la polea alta y arrodillate de frente. Sujeta la cuerda con agarre neutral y mantiene la espalda recta al inicio. Contrae el abdomen para redondear la espalda hacia adelante, manteniendo los extremos de la cuerda cerca de las orejas. Al llegar al maximo, regresa lento a la posicion inicial. Evita bajar demasiado para no involucrar los flexores de cadera.' }, image: require('../assets/workout-api-images/cable-crunches.svg') },
  { id: 'ex-72', name: 'AB Wheel', name_i18n: { es: 'Rueda abdominal' }, category: 'Body weight', muscles: {     abs: 0.8,     shoulders: 0.067,     triceps: 0.067,     obliques: 0.067 }, description: 'Kneel down (preferably on a mat) and grab the AB Wheel in front of you while bending forward. Roll it as far as possible while engaging your abs until your back is straight. Hold this extended position for 2 or 3 seconds, then contract your abs to roll the wheel back to the starting position. Keep your arms and knees close together throughout the movement.', description_i18n: { es: 'Arrodillate en una colchoneta y sujeta la rueda abdominal al frente. Rueda hacia adelante todo lo que puedas mientras mantienes el abdomen activo y la espalda recta. Sosten la posicion extendida 2 o 3 segundos y regresa contrayendo el abdomen. Mantiene brazos y rodillas alineados.' }, image: require('../assets/workout-api-images/ab-wheel.svg') },
  { id: 'ex-73', name: 'Hanging leg raises', name_i18n: { es: 'Elevaciones de piernas colgado' }, category: 'Body weight', muscles: {     abs: 0.8,     obliques: 0.2 }, description: 'Grab the bar with an overhand grip (palms facing away), keep your body straight and abs engaged to avoid swinging. Contract your abs to lift your legs in front of you while keeping them straight. Touch the bar with your feet (or get as close as possible), then control the descent back to the starting position. This exercise can also be performed with bent knees at 90 deg to make it easier.', description_i18n: { es: 'Sujeta la barra con agarre pronado y mantiene el cuerpo recto para evitar balanceos. Contrae el abdomen para elevar las piernas rectas al frente, intentando tocar la barra con los pies o llegar lo mas cerca posible. Controla el descenso hasta la posicion inicial. Puedes hacerlo con rodillas flexionadas a 90 deg para facilitar.' }, image: require('../assets/workout-api-images/hanging-leg-raises.svg') },
  { id: 'ex-74', name: 'Squat', name_i18n: { es: 'Sentadilla' }, category: 'Free weight', muscles: {     glutes: 0.4,     quadriceps: 0.4,     hamstrings: 0.1,     adductors: 0.1 }, description: 'Place a bar on a rack at a suitable height. Rest the bar on your traps behind your neck, then straighten your legs to lift it off the rack. Step back slightly and position your feet shoulder-width apart or slightly wider. Keep your back straight and your abs tight, bend your knees while focusing the load on your heels to maintain balance. Imagine sitting down on a chair and keep a straight path throughout the movement. Once you reach the bottom (depth depends on your mobility), contract your quads and glutes to lift the bar back up. After your set, carefully rack the bar. Always keep your back straight and avoid pushing your knees too far forward during the squat.', description_i18n: { es: 'Coloca la barra en el rack a una altura adecuada. Apoya la barra sobre los trapecios detras del cuello y extiende las piernas para sacarla. Da un paso atras y coloca los pies al ancho de los hombros o un poco mas. Con la espalda recta y el abdomen firme, flexiona las rodillas llevando el peso a los talones. Imagina sentarte en una silla y baja hasta donde tu movilidad permita. Contrae gluteos y cuadriceps para subir. Vuelve a colocar la barra con cuidado al terminar.' }, image: require('../assets/workout-api-images/squat.svg') },
  { id: 'ex-75', name: 'Pistol squat', name_i18n: { es: 'Sentadilla pistol' }, category: 'Body weight', muscles: {     glutes: 0.4,     quadriceps: 0.4,     hamstrings: 0.2 }, description: 'Stand upright with your arms down at your sides. While balancing on one leg, perform a squat, going as low as your mobility allows. As you descend, extend your arms in front of you to help distribute your weight and maintain alignment. At the bottom, contract your quadriceps to return to the starting position, then repeat with the opposite leg. Make sure not to let your knee move too far forward during the descent.', description_i18n: { es: 'De pie con los brazos a los lados, equilibra el peso en una pierna. Baja en sentadilla lo mas que tu movilidad permita mientras extiendes los brazos al frente para equilibrarte. En el fondo, contrae el cuadriceps para volver arriba. Repite con la otra pierna. Evita que la rodilla se vaya demasiado hacia adelante.' }, image: require('../assets/workout-api-images/pistol-squat.svg') },
  { id: 'ex-76', name: 'Front Squat', name_i18n: { es: 'Sentadilla frontal' }, category: 'Free weight', muscles: {     quadriceps: 0.8,     glutes: 0.067,     hamstrings: 0.067,     adductors: 0.067 }, description: 'Set a barbell on a rack at a height that suits you. Rest the bar on the front of your shoulders and grip it with your palms facing up (you can also cross your arms over the bar to reduce wrist strain). Stand up to lift the bar off the rack. Step back slightly and position your feet shoulder-width apart or a bit wider. With your back straight and abs tight, bend your knees, keeping your weight on your heels for balance. Lower yourself as if sitting in a chair, maintaining a straight movement path. Once you reach the bottom (depth depending on your mobility), contract your quads and glutes to return to the starting position. After your set, re-rack the bar. Always keep your back straight and avoid pushing your knees too far forward.', description_i18n: { es: 'Coloca la barra en el rack a una altura adecuada. Apoya la barra en la parte frontal de los hombros y sujeta con palmas hacia arriba, o cruza los brazos sobre la barra. Levanta la barra y da un paso atras. Con la espalda recta y el abdomen firme, flexiona las rodillas llevando el peso a los talones. Baja hasta donde tu movilidad permita y vuelve arriba contrayendo cuadriceps y gluteos. Coloca la barra en el soporte al terminar.' }, image: require('../assets/workout-api-images/front-squat.svg') },
  { id: 'ex-77', name: 'Leg extension', name_i18n: { es: 'Extension de piernas' }, category: 'Machine', muscles: {     quadriceps: 1 }, description: 'Sit on the machine with your back flat against the pad. Place your feet under the pad so that it rests near your ankles. Contract your quadriceps to lift the pad, extending your legs fully. Then, control the descent back to the starting position and repeat. This exercise can also be performed unilaterally, one leg at a time.', description_i18n: { es: 'Sientate en la maquina con la espalda pegada al respaldo. Coloca los pies bajo el rodillo cerca de los tobillos. Contrae los cuadriceps para extender las piernas completamente. Luego baja con control a la posicion inicial y repite. Puedes hacerlo unilateral si lo deseas.' }, image: require('../assets/workout-api-images/leg-extension.svg') },
  { id: 'ex-78', name: 'Jump squat', name_i18n: { es: 'Sentadilla con salto' }, category: 'Body weight', muscles: {     glutes: 0.4,     quadriceps: 0.4,     hamstrings: 0.1,     adductors: 0.1 }, description: 'Stand with your feet shoulder-width apart or slightly wider. Extend your arms or clasp your hands in front of you, then bend your legs to perform a squat. Go as low as your mobility allows. At the bottom of the movement, jump explosively by contracting your quadriceps, landing softly on the balls of your feet and bending your legs to absorb the impact. Keep your back straight throughout the movement.', description_i18n: { es: 'De pie con los pies al ancho de los hombros o un poco mas, lleva los brazos al frente. Baja en sentadilla hasta donde tu movilidad permita. En el fondo, salta de forma explosiva contrayendo los cuadriceps, y aterriza suave sobre las puntas de los pies flexionando las rodillas para absorber el impacto. Mantiene la espalda recta.' }, image: require('../assets/workout-api-images/jump-squat.svg') },
  { id: 'ex-79', name: 'Jumping Jacks', name_i18n: { es: 'Saltos de tijera' }, category: 'Body weight', muscles: {     glutes: 0.4,     quadriceps: 0.4,     adductors: 0.1,     calves: 0.1 }, description: 'Stand upright with your feet shoulder-width apart and your arms at your sides. Jump and spread your legs wider while raising your arms to the sides until your hands meet above your head. Jump again to return to the starting position, lowering your arms back to your sides and bringing your feet back to shoulder-width. Keep your posture upright throughout the movement.', description_i18n: { es: 'De pie con los pies al ancho de los hombros y brazos a los lados. Salta abriendo las piernas mientras elevas los brazos hasta juntarlos sobre la cabeza. Salta de nuevo para volver a la posicion inicial bajando los brazos y cerrando las piernas. Mantiene la postura erguida.' }, image: require('../assets/workout-api-images/jumping-jacks.svg') },
  { id: 'ex-80', name: 'Lunges', name_i18n: { es: 'Zancadas' }, category: 'Body weight', muscles: {     glutes: 0.4,     quadriceps: 0.4,     hamstrings: 0.2 }, description: 'Stand with your feet hip-width apart. Step forward and bend the front leg until it forms a 90 deg angle, keeping your torso upright. Your rear leg should be supported on the ball of the foot, parallel to the ground. Push through the front leg to return to the starting position. You can continue alternating legs or perform all reps on one side. Keep your back straight and avoid letting your knees go too far forward during the lunge.', description_i18n: { es: 'De pie con los pies al ancho de caderas. Da un paso al frente y flexiona la pierna delantera hasta formar un angulo de 90 deg, con el torso erguido. La pierna trasera queda apoyada en la punta del pie. Empuja con la pierna delantera para volver a la posicion inicial. Alterna las piernas o completa todas las repeticiones por lado. Mantiene la espalda recta.' }, image: require('../assets/workout-api-images/lunges.svg') },
  { id: 'ex-81', name: 'Jumping lunges', name_i18n: { es: 'Zancadas con salto' }, category: 'Body weight', muscles: {     glutes: 0.4,     quadriceps: 0.4,     hamstrings: 0.2 }, description: 'Stand with your feet hip-width apart. Step forward and bend the front leg to form a 90 deg angle, keeping your torso upright. Your back leg should be on the ball of the foot, parallel to the ground. Explosively push off the front leg to jump and switch legs mid-air, landing with the opposite leg forward. Land softly on the balls of your feet and bend your knees to absorb the impact. Repeat by alternating legs. Keep your back straight and avoid pushing your knees too far forward.', description_i18n: { es: 'De pie con los pies al ancho de caderas. Da un paso al frente y flexiona la pierna delantera a 90 deg, con el torso erguido. Impulsate con la pierna delantera para saltar y cambiar las piernas en el aire. Aterriza suave sobre las puntas de los pies y flexiona las rodillas para absorber el impacto. Repite alternando piernas.' }, image: require('../assets/workout-api-images/jumping-lunges.svg') },
  { id: 'ex-82', name: 'Leg press', name_i18n: { es: 'Prensa de piernas' }, category: 'Machine', muscles: {     glutes: 0.4,     quadriceps: 0.4,     hamstrings: 0.1,     adductors: 0.1 }, description: 'Sit down with your back pressed firmly against the backrest. Place your feet shoulder-width apart on the platform, positioning them higher or lower depending on the muscle focus. Unlock the press using the handles, then extend your legs without locking your knees to release the weight. Bend your legs to lower the platform in a controlled manner, going as low as your mobility allows. Once at the bottom, contract your quads and glutes to push the platform back to the starting position. Keep your back and glutes in contact with the seat at all times, and avoid locking your knees when extending your legs.', description_i18n: { es: 'Sientate con la espalda apoyada en el respaldo. Coloca los pies al ancho de los hombros en la plataforma, mas arriba o abajo segun el enfoque. Desbloquea la prensa y extiende las piernas sin bloquear las rodillas. Baja la plataforma con control hasta donde tu movilidad permita. Empuja con cuadriceps y gluteos para volver a la posicion inicial. Mantiene la espalda y gluteos pegados al asiento.' }, image: require('../assets/workout-api-images/leg-press.svg') },
  { id: 'ex-83', name: 'Hack squat', name_i18n: { es: 'Sentadilla hack' }, category: 'Machine', muscles: {     glutes: 0.4,     quadriceps: 0.4,     hamstrings: 0.1,     adductors: 0.1 }, description: 'Step onto the platform with your back pressed firmly against the backrest and position yourself between the shoulder pads. Place your feet shoulder-width apart on the platform, adjusting their position depending on the muscle focus. Unlock the sled using the handles and extend your legs without locking your knees to engage the weight. Bend your knees to lower the sled in a controlled motion, stopping as low as your mobility allows. Once at the bottom, contract your quads and glutes to push the sled back to the starting position. Keep your back in contact with the pad at all times, maintain an upright torso, and avoid locking your knees at the top.', description_i18n: { es: 'Colocate en la plataforma con la espalda apoyada en el respaldo y los hombros bajo las almohadillas. Coloca los pies al ancho de los hombros y ajusta su posicion segun el enfoque muscular. Desbloquea el trineo y extiende las piernas sin bloquear las rodillas. Baja en sentadilla con control hasta donde tu movilidad permita. Empuja con cuadriceps y gluteos para volver arriba. Mantiene la espalda apoyada y evita bloquear las rodillas al final.' }, image: require('../assets/workout-api-images/hack-squat.svg') },
  { id: 'ex-84', name: 'Wall sit', name_i18n: { es: 'Silla en pared' }, category: 'Body weight', muscles: {     quadriceps: 1 }, description: 'Stand with your back against a wall, feet shoulder-width apart or slightly wider. Lower yourself by bending your knees until they form a 90-degree angle. Rest your hands on your thighs or against the wall. Engage your thighs and hold this position for the desired duration, focusing your weight on your heels. Keep your back pressed firmly against the wall throughout the exercise.', description_i18n: { es: 'Apoya la espalda en la pared con los pies al ancho de los hombros. Baja flexionando las rodillas hasta formar un angulo de 90 deg. Apoya las manos en los muslos o en la pared. Mantiene el peso en los talones y sostiene la posicion el tiempo indicado, con la espalda pegada a la pared.' }, image: require('../assets/workout-api-images/wall-sit.svg') },
  { id: 'ex-85', name: 'Burpees', name_i18n: { es: 'Burpees' }, category: 'Body weight', muscles: {     glutes: 0.4,     quadriceps: 0.4,     shoulders: 0.04,     chest: 0.04,     triceps: 0.04,     hamstrings: 0.04,     calves: 0.04 }, description: 'Stand with your feet shoulder-width apart or slightly wider. Bend your knees to perform a squat and place your hands on the ground at the bottom of the movement. While crouching, support your weight with your arms and kick your legs back to get into a plank position. Perform a push-up while keeping your body tight and your back straight. Then bring your feet back to your hands, returning to the bottom of a squat. Explosively jump up by contracting your quads and raising your arms for momentum. Land softly on your toes with bent knees to absorb the impact. Continue immediately by squatting again.', description_i18n: { es: 'De pie con los pies al ancho de los hombros. Baja en sentadilla y apoya las manos en el suelo. Lanza las piernas hacia atras para quedar en plancha. Realiza una flexion con el cuerpo firme. Lleva los pies de nuevo hacia las manos, vuelve a la sentadilla y salta de forma explosiva elevando los brazos. Aterriza suave y repite.' }, image: require('../assets/workout-api-images/burpees.svg') },
  { id: 'ex-86', name: 'Goblet squat', name_i18n: { es: 'Sentadilla goblet' }, category: 'Free weight', muscles: {     glutes: 0.4,     quadriceps: 0.4,     hamstrings: 0.1,     adductors: 0.1 }, description: 'Stand with your feet shoulder-width apart or slightly wider. Grab a dumbbell vertically with your palms facing the plate, and bring it up to chest level with your elbows bent. Keep your back straight and your core tight. Bend your knees and push your hips back as if sitting in a chair, keeping the weight centered over your heels. Descend as low as your mobility allows, then contract your quads and glutes to return to the starting position. Make sure to keep your back straight and avoid letting your knees move too far forward.', description_i18n: { es: 'De pie con los pies al ancho de los hombros, sujeta una mancuerna en posicion vertical frente al pecho. Mantiene la espalda recta y el core firme. Flexiona las rodillas y lleva las caderas atras como si te sentaras. Baja hasta donde tu movilidad permita y vuelve arriba contrayendo cuadriceps y gluteos. Evita que las rodillas se vayan demasiado hacia adelante.' }, image: require('../assets/workout-api-images/goblet-squat.svg') },
  { id: 'ex-87', name: 'Leg curl', name_i18n: { es: 'Curl femoral' }, category: 'Machine', muscles: {     hamstrings: 1 }, description: 'Lie face down on the machine and place your feet under the pad, positioning it just above your heels. Grab the handles in front of you. Contract your hamstrings to bring the pad closer to your glutes. Slowly lower the weight back to the starting position without fully locking your knees, and repeat. This exercise can also be performed unilaterally, one leg at a time.', description_i18n: { es: 'Acuestate boca abajo en la maquina y coloca los pies bajo el rodillo, justo encima de los talones. Sujeta las manijas. Contrae los isquiotibiales para llevar el rodillo hacia los gluteos. Baja con control sin bloquear las rodillas y repite. Puedes hacerlo unilateral si lo deseas.' }, image: require('../assets/workout-api-images/leg-curl.svg') },
  { id: 'ex-88', name: 'Stiff leg deadlift', name_i18n: { es: 'Peso muerto piernas rigidas' }, category: 'Free weight', muscles: {     glutes: 0.4,     hamstrings: 0.35,     midBack: 0.15,     adductors: 0.1 }, description: 'Stand in front of the barbell placed on the floor. Bend forward while keeping your back straight and legs slightly bent to grasp the bar with a pronated grip (palms facing you). Engage your lower back to lift your torso up, keeping your legs nearly straight. Pause briefly at the top, then lower the bar back to the floor while keeping your back straight. Keep your shoulders pulled back throughout the movement.', description_i18n: { es: 'De pie frente a la barra, inclina el torso con la espalda recta y las piernas ligeramente flexionadas para sujetar la barra con agarre pronado. Levanta el torso activando la zona lumbar y manteniendo las piernas casi rectas. Pausa breve arriba y baja la barra con control hasta el suelo sin redondear la espalda. Mantiene los hombros atras durante el movimiento.' }, image: require('../assets/workout-api-images/stiff-leg-deadlift.svg') },
  { id: 'ex-89', name: 'Kettlebell swing', name_i18n: { es: 'Balanceo con kettlebell' }, category: 'Free weight', muscles: {     glutes: 0.4,     hamstrings: 0.4,     shoulders: 0.1,     quadriceps: 0.1 }, description: 'Stand with your feet shoulder-width apart or slightly wider. Bend your knees and hinge at the hips while keeping your back straight to grab the kettlebell with both hands. Initiate a slight swing with your hips and push with your legs to drive the kettlebell upward in front of you with straight arms, ideally until it\'s at eye level. Your arms should merely guide the movement, with minimal effort. Once at the top, control the descent, allowing the kettlebell to swing between your legs, then use your hips to continue the motion. Keep your back straight throughout the movement. If you\'re comfortable, you can swing the kettlebell overhead.', description_i18n: { es: 'De pie con los pies al ancho de los hombros, flexiona las rodillas e inclina la cadera para sujetar la kettlebell con ambas manos. Inicia el balanceo con la cadera y empuja con las piernas para llevar la kettlebell al frente con los brazos rectos hasta la altura de los ojos. Los brazos solo guian el movimiento. Controla la bajada dejando que pase entre las piernas y continua el ciclo. Mantiene la espalda recta.' }, image: require('../assets/workout-api-images/kettlebell-swing.svg') },
  { id: 'ex-90', name: 'Adductor machine', name_i18n: { es: 'Maquina de aductores' }, category: 'Machine', muscles: {     adductors: 1 }, description: 'Sit on the machine with your back pressed against the backrest. Position your legs so that the insides of your thighs and your feet rest against the pads. Squeeze your legs together by contracting your adductors, then slowly control the return to the starting position.', description_i18n: { es: 'Sientate en la maquina con la espalda apoyada. Coloca las piernas y los pies contra las almohadillas internas. Aprieta las piernas juntandolas al contraer los aductores, luego vuelve lento a la posicion inicial con control.' }, image: require('../assets/workout-api-images/adductor-machine.svg') },
  { id: 'ex-91', name: 'Abductors machine', name_i18n: { es: 'Maquina de abductores' }, category: 'Machine', muscles: {     abductors: 1 }, description: 'Sit on the machine with your back pressed against the backrest. Position your legs so that the outsides of your thighs and your feet rest against the pads. Push your legs outward by contracting your abductors, then slowly control the return to the starting position.', description_i18n: { es: 'Sientate en la maquina con la espalda apoyada. Coloca las piernas y los pies contra las almohadillas externas. Empuja las piernas hacia afuera contrayendo los abductores, luego vuelve lento a la posicion inicial con control.' }, image: require('../assets/workout-api-images/abductors-machine.svg') },
  { id: 'ex-92', name: 'Standing calf raises', name_i18n: { es: 'Elevaciones de gemelos de pie' }, category: 'Machine', muscles: {     calves: 1 }, description: 'Stand facing the machine with the balls of your feet on the edge of the platform. Adjust the shoulder pads to rest on your shoulders. With legs straight and back upright, raise your heels by contracting your calves to stand on your tiptoes. Then lower your heels slowly to return to the starting position.', description_i18n: { es: 'De pie en la maquina con las puntas de los pies en el borde de la plataforma. Ajusta las almohadillas sobre los hombros. Con las piernas rectas y la espalda erguida, eleva los talones contrayendo los gemelos hasta quedar en puntas. Baja lento a la posicion inicial.' }, image: require('../assets/workout-api-images/standing-calf-raises.svg') },
  { id: 'ex-93', name: 'Seated calf raises', name_i18n: { es: 'Elevaciones de gemelos sentado' }, category: 'Machine', muscles: {     calves: 1 }, description: 'Sit on the machine seat and adjust the pads so they rest securely on your thighs. Unlock the weight by raising your heels using your calves, lifting onto the balls of your feet. Then lower your heels slowly back to the starting position.', description_i18n: { es: 'Sientate en la maquina y ajusta las almohadillas para que queden sobre los muslos. Desbloquea el peso elevando los talones y sube a puntas. Luego baja lento los talones a la posicion inicial.' }, image: require('../assets/workout-api-images/seated-calf-raises.svg') },
];

export const CATEGORIES = ['All', 'Free weigth', 'Body weight', 'Machine', 'Cable']

export const getExerciseText = (exercise, language) => {
  if (!exercise) return { name: '', description: '' };
  const name = exercise.name_i18n?.[language] || exercise.name;
  const description = exercise.description_i18n?.[language] || exercise.description;
  return { name, description };
};

export const getExerciseName = (exercise, language) =>
  getExerciseText(exercise, language).name;

export const getExerciseDescription = (exercise, language) =>
  getExerciseText(exercise, language).description;

export const getExerciseById = (id) => EXERCISE_CATALOG.find((e) => e.id === id);
